CREATE DATABASE CRIME;
GO

USE CRIME;
GO

CREATE TABLE crime_scene (
	date	DATE,
	type	VARCHAR(100),
	city	VARCHAR(100),
	country	VARCHAR(100),
	description	VARCHAR(MAX),
	PRIMARY KEY (date, type, city, country)
);
INSERT INTO crime_scene VALUES('2018-01-06','murder','Chattanooga','United States','The two young people greeted each other affectionately, and momentarily blocked the Dover Street Tube exit in doing so. The adjective “old” was misleading. Their united ages would certainly not have totalled forty-five.');INSERT INTO crime_scene VALUES('2018-03-07','assault','Brooklyn','United States','');INSERT INTO crime_scene VALUES('2018-01-07','fraud','Shawnee Mission','United States','The place was full, and they wandered about looking for a table, catching odds and ends of conversation as they did so.');INSERT INTO crime_scene VALUES('2018-03-03','theft','Cincinnati','United States','Tuppence, though utterly taken aback, nevertheless kept her head. She had not the faintest comprehension of his meaning, but she was naturally quick-witted, and felt it imperative to “keep her end up” as she phrased it.');INSERT INTO crime_scene VALUES('2018-09-25','fraud','Philadelphia','United States','');INSERT INTO crime_scene VALUES('2018-09-27','assault','Los Angeles','United States','');INSERT INTO crime_scene VALUES('2018-01-02','arson','Tampa','US','“Yes?” Her grave eyes met his inquiringly.');INSERT INTO crime_scene VALUES('2018-09-14','theft','Greenville','United States','“Afraid—you—might—be—late! Oh, Lord, I give it up!” said Mr. Beresford.');INSERT INTO crime_scene VALUES('2018-01-08','arson','Joliet','United States','But at that moment two elderly ladies rose and collected parcels, and Tuppence deftly ensconced herself in one of the vacant seats.');INSERT INTO crime_scene VALUES('2018-01-02','assault','Grand Junction','US','It was 2 p.m. on the afternoon of May 7, 1915. The Lusitania had been struck by two torpedoes in succession and was sinking rapidly, while the boats were being launched with all possible speed. The women and children were being lined up awaiting their turn. Some still clung desperately to husbands and fathers; others clutched their children closely to their breasts. One girl stood alone, slightly apart from the rest. She was quite young, not more than eighteen. She did not seem afraid, and her grave, steadfast eyes looked straight ahead.');INSERT INTO crime_scene VALUES('2018-02-17','arson','Valdosta','United States','''‘But about his toes?’ the Mock Turtle persisted. ‘How COULD he turn them');INSERT INTO crime_scene VALUES('2018-02-21','murder','New Haven','United States','He raised his hat with a flourish, and walked away. Tuppence remained for some minutes gazing after him. Then she gave a curious movement of her shoulders, rather as a terrier shakes himself.');INSERT INTO crime_scene VALUES('2018-03-15','fraud','Spartanburg','United States','''as well as she could for sneezing.');INSERT INTO crime_scene VALUES('2018-09-16','theft','Erie','United States','“You did that part of it very well, old bean, but all the same the fellow wasn’t taken in—not for a moment!”');INSERT INTO crime_scene VALUES('2018-03-13','robbery','Charlotte','United States','');INSERT INTO crime_scene VALUES('2018-08-11','arson','Saint Petersburg','United States','“As I said once before,” said Whittington angrily, “quit fooling, and come to the point. You can’t play the innocent with me. You know a great deal more than you’re willing to admit.”');INSERT INTO crime_scene VALUES('2018-01-07','assault','Los Angeles','United States','I should think I did! Wasn’t the old cat in a rage when she found out? Not that she was a bad sort really, old Mother Greenbank! Good old hospital—demobbed like everything else, I suppose?');INSERT INTO crime_scene VALUES('2018-01-08','robbery','Tampa','United States','“Very well.” Tuppence helped herself liberally to buttered toast. “Abridged biography of Miss Prudence Cowley, fifth daughter of Archdeacon Cowley of Little Missendell, Suffolk. Miss Cowley left the delights (and drudgeries) of her home life early in the war and came up to London, where she entered an officers’ hospital. First month: Washed up six hundred and forty-eight plates every day. Second month: Promoted to drying aforesaid plates. Third month: Promoted to peeling potatoes. Fourth month: Promoted to cutting bread and butter. Fifth month: Promoted one floor up to duties of wardmaid with mop and pail. Sixth month: Promoted to waiting at table. Seventh month: Pleasing appearance and nice manners so striking that am promoted to waiting on the Sisters! Eighth month: Slight check in career. Sister Bond ate Sister Westhaven’s egg! Grand row! Wardmaid clearly to blame! Inattention in such important matters cannot be too highly censured. Mop and pail again! How are the mighty fallen!');INSERT INTO crime_scene VALUES('2018-02-28','assault','Sunnyvale','United States','');INSERT INTO crime_scene VALUES('2018-08-12','assault','Odessa','United States','');INSERT INTO crime_scene VALUES('2018-08-10','arson','Evansville','United States','');INSERT INTO crime_scene VALUES('2018-02-25','fraud','Houston','United States','Tuppence knew the name well. Nothing could have been more select. She had had several American friends there. She was more than ever puzzled.');INSERT INTO crime_scene VALUES('2018-03-11','murder','Chicago','United States','''The King and Queen of Hearts were seated on their throne when they');INSERT INTO crime_scene VALUES('2018-08-01','assault','Trenton','United States','');INSERT INTO crime_scene VALUES('2018-03-15','assault','Madison','United States','''wag my tail when I’m angry. Therefore I’m mad.’');INSERT INTO crime_scene VALUES('2018-01-10','robbery','Champaign','United States','''All the time they were playing the Queen never left off quarrelling with');INSERT INTO crime_scene VALUES('2018-02-23','assault','Miami','United States','After handing it over the counter she set out briskly for home, stopping at a baker’s to buy three penny-worth of new buns.

');INSERT INTO crime_scene VALUES('2018-09-16','robbery','Tallahassee','United States','');INSERT INTO crime_scene VALUES('2018-02-26','murder','Memphis','United States','My great pal in gaol was a little American mate. I dare say I picked it up from him. I can soon get out of it again');INSERT INTO crime_scene VALUES('2018-11-02','murder','Sequel City','United States','Tuppence turned sharply, but the words hovering on the tip of her tongue remained unspoken, for the man’s appearance and manner did not bear out her first and most natural assumption. She hesitated.');INSERT INTO crime_scene VALUES('2018-02-25','fraud','Los Angeles','United States','');INSERT INTO crime_scene VALUES('2018-02-18','murder','Sequel City','United States','A security camera in the neighborhood captured two figures who may be witnesses. The first one lives at 513 Hamilton Dr. The second one was tentatively identified by one of the police officers as a man named George, who lives on Independence St.');INSERT INTO crime_scene VALUES('2018-09-13','theft','New Orleans','United States','“Well,” said Mr. Beresford, at length able to relieve his feelings, “what the—dickens, did you want to take a taxi for?”');INSERT INTO crime_scene VALUES('2018-12-29','arson','Pompano Beach','United States','');INSERT INTO crime_scene VALUES('2018-09-07','fraud','Orange','United States','The cab drew up outside the tube station. Tommy was just within the entrance. His eyes opened to their fullest extent as he hurried forward to assist Tuppence to alight. She smiled at him affectionately, and remarked in a slightly affected voice:');INSERT INTO crime_scene VALUES('2018-09-11','murder','Des Moines','United States','');INSERT INTO crime_scene VALUES('2018-09-12','fraud','Honolulu','United States','“I think you’ve given him too much, Tommy,” said Tuppence innocently. “I fancy he wants to give some of it back.”');INSERT INTO crime_scene VALUES('2018-09-07','robbery','Garden Grove','United States','');INSERT INTO crime_scene VALUES('2018-09-13','arson','Orange','United States','');INSERT INTO crime_scene VALUES('2018-08-01','murder','Dallas','United States','It is a universally acknowlegded truth that');INSERT INTO crime_scene VALUES('2018-02-24','arson','Portland','United States','Tuppence knocked. In response to a voice from within, she turned the handle and walked into a small rather dirty outer office.');INSERT INTO crime_scene VALUES('2018-02-28','arson','Lansing','United States','“No?” said Whittington softly. “Well, I will tell you. I could doubtless obtain some one else for very much less. What I am willing to pay for is a young lady with sufficient intelligence and presence of mind to sustain her part well, and also one who will have sufficient discretion not to ask too many questions.”');INSERT INTO crime_scene VALUES('2018-03-08','theft','Denver','United States','');INSERT INTO crime_scene VALUES('2018-01-05','theft','Philadelphia','United States','“Because of ‘women and children first.’” He looked round and lowered his voice. “I’m carrying papers—vitally important papers. They may make all the difference to the Allies in the war. You understand? These papers have got to be saved! They’ve more chance with you than with me. Will you take them?”');INSERT INTO crime_scene VALUES('2018-08-04','theft','Colorado Springs','United States','');INSERT INTO crime_scene VALUES('2018-08-30','arson','Grand Junction','United States','Whittington snatched it up and read it. A frown gathered on his brow.');INSERT INTO crime_scene VALUES('2018-02-23','murder','London','United States','It wanted some five minutes to eleven when Tuppence reached the block of buildings in which the offices of the Esthonia Glassware Co. were situated. To arrive before the time would look over-eager. So Tuppence decided to walk to the end of the street and back again. She did so. On the stroke of eleven she plunged into the recesses of the building. The Esthonia Glassware Co. was on the top floor. There was a lift, but Tuppence chose to walk up.

');INSERT INTO crime_scene VALUES('2018-02-23','murder','Miami','United States','Slightly out of breath, she came to a halt outside the ground glass door with the legend painted across it “Esthonia Glassware Co.”

');INSERT INTO crime_scene VALUES('2018-09-02','arson','Iowa City','United States','');INSERT INTO crime_scene VALUES('2018-03-02','arson','Honolulu','United States','');INSERT INTO crime_scene VALUES('2018-09-11','robbery','Tyler','United States','“I think you’ve given him too much, Tommy,” said Tuppence innocently. “I fancy he wants to give some of it back.”');INSERT INTO crime_scene VALUES('2018-03-13','arson','Jacksonville','United States','');INSERT INTO crime_scene VALUES('2018-03-12','assault','Ogden','United States','');INSERT INTO crime_scene VALUES('2018-09-15','fraud','San Diego','United States','');INSERT INTO crime_scene VALUES('2018-09-27','arson','Little Rock','United States','');INSERT INTO crime_scene VALUES('2018-09-28','arson','Mobile','United States','');INSERT INTO crime_scene VALUES('2018-09-04','arson','Colorado Springs','United States','Tuppence sped lightly down the stairs. A wild elation possessed her. A neighbouring clock showed the time to be five minutes to twelve.');INSERT INTO crime_scene VALUES('2018-08-06','assault','Clearwater','United States','');INSERT INTO crime_scene VALUES('2018-07-31','murder','Newark','United States','Mr. Whittington brought his fist down upon the desk with a bang.');INSERT INTO crime_scene VALUES('2018-08-04','assault','Denver','United States','');INSERT INTO crime_scene VALUES('2018-07-28','theft','Atlanta','United States','');INSERT INTO crime_scene VALUES('2018-08-12','assault','Lancaster','United States','');INSERT INTO crime_scene VALUES('2018-12-28','murder','El Paso','United States','');INSERT INTO crime_scene VALUES('2018-03-09','theft','Dallas','United States','');INSERT INTO crime_scene VALUES('2018-03-06','theft','Fullerton','United States','');INSERT INTO crime_scene VALUES('2018-03-06','theft','Rochester','United States','');INSERT INTO crime_scene VALUES('2018-08-06','theft','Winter Haven','United States','');INSERT INTO crime_scene VALUES('2018-03-06','assault','Durham','United States','');INSERT INTO crime_scene VALUES('2018-09-01','fraud','Topeka','United States','');INSERT INTO crime_scene VALUES('2018-03-03','murder','Bakersfield','United States','Tuppence’s conscience gave her a passing twinge as she remembered the archdeacon. She seized hurriedly on the first name that came into her head.');INSERT INTO crime_scene VALUES('2018-09-25','robbery','Providence','United States','“Your last supposition is the correct one. I have come into money, and the shock has been too much for me! For that particular form of mental trouble an eminent physician recommends unlimited Hors d’œuvre, Lobster à l’américane, Chicken Newberg, and Pêche Melba! Let’s go and get them!”');INSERT INTO crime_scene VALUES('2018-09-20','assault','Waco','United States','');INSERT INTO crime_scene VALUES('2018-09-25','theft','Houston','United States','');INSERT INTO crime_scene VALUES('2018-02-24','fraud','Boston','United States','A middle-aged clerk got down from a high stool at a desk near the window and came towards her inquiringly.');INSERT INTO crime_scene VALUES('2018-02-27','murder','Brooklyn','United States','');INSERT INTO crime_scene VALUES('2018-08-30','fraud','Sioux Falls','United States','');INSERT INTO crime_scene VALUES('2018-02-24','murder','Detroit','United States','Mr. Whittington was seated behind a large desk covered with papers. Tuppence felt her previous judgment confirmed. There was something wrong about Mr. Whittington. The combination of his sleek prosperity and his shifty eye was not attractive.');INSERT INTO crime_scene VALUES('2018-08-29','theft','Newport News','United States','The clerk followed his discreet knock into the room, and laid a paper at his master’s elbow.');INSERT INTO crime_scene VALUES('2018-01-04','robbery','Chattanooga','United States','She noticed now that he was greatly agitated. There were beads of perspiration on his brow. He was evidently in a state of overmastering fear. And yet he did not strike her as the kind of man who would be afraid to meet death!');INSERT INTO crime_scene VALUES('2018-08-08','assault','Harrisburg','United States','');INSERT INTO crime_scene VALUES('2018-12-28','assault','Austin','United States','Tuppence raised her face to his. The taxi proceeded on its course round the north side of Regent’s Park.');INSERT INTO crime_scene VALUES('2018-01-09','assault','Lees Summit','United States','Tuppence nodded gloomily.

“What about the colonies?” she suggested.');INSERT INTO crime_scene VALUES('2018-07-28','theft','London','United States','');INSERT INTO crime_scene VALUES('2018-08-02','arson','Tucson','United States','');INSERT INTO crime_scene VALUES('2018-09-15','robbery','Birmingham','United States','');INSERT INTO crime_scene VALUES('2018-09-23','theft','Albany','United States','');INSERT INTO crime_scene VALUES('2018-11-02','robbery','Chicago','United States','“I’ve got an old uncle who’s more or less rolling, but he’s no good.”');INSERT INTO crime_scene VALUES('2018-01-06','fraud','Chattanooga','United States','The Lusitania settled with a more decided list to starboard. In answer to a quick command, the girl went forward to take her place in the boat.

');INSERT INTO crime_scene VALUES('2018-02-26','assault','Des Moines','United States','None whatever. You would, of course, go in the character of my ward, and you would hold no communication with your friends. I should have to request absolute secrecy for the time being. By the way, you are English, are you not?');INSERT INTO crime_scene VALUES('2018-02-22','assault','Brooklyn','United States','“The adventures have begun,” she murmured to herself. “What does he want me to do, I wonder? There’s something about you, Mr. Whittington, that I don’t like at all. But, on the other hand, I’m not the least bit afraid of you. And as I’ve said before, and shall doubtless say again, little Tuppence can look after herself, thank you!”');INSERT INTO crime_scene VALUES('2018-09-01','murder','Fort Pierce','United States','The clerk withdrew, closing the door behind him. Whittington turned to Tuppence.');INSERT INTO crime_scene VALUES('2018-03-11','fraud','Jamaica','United States','');INSERT INTO crime_scene VALUES('2018-09-08','robbery','Madison','United States','''');INSERT INTO crime_scene VALUES('2018-08-07','murder','Oakland','United States','');INSERT INTO crime_scene VALUES('2018-07-29','arson','Shreveport','United States','');INSERT INTO crime_scene VALUES('2018-03-10','assault','Van Nuys','United States','');INSERT INTO crime_scene VALUES('2018-09-09','theft','Los Angeles','United States','');INSERT INTO crime_scene VALUES('2018-03-15','robbery','Reston','United States','''felt certain it must be really offended. ‘We won’t talk about her any');INSERT INTO crime_scene VALUES('2018-09-24','robbery','San Diego','United States','');INSERT INTO crime_scene VALUES('2018-03-09','robbery','Staten Island','United States','');INSERT INTO crime_scene VALUES('2018-09-03','assault','Durham','United States','“Exactly. Au revoir!” Whittington looked almost genial again, a reversion that aroused in Tuppence a faint misgiving. “Au revoir, my clever and charming young lady.”');INSERT INTO crime_scene VALUES('2018-09-13','assault','Birmingham','United States','');INSERT INTO crime_scene VALUES('2018-09-15','assault','Omaha','United States','''');INSERT INTO crime_scene VALUES('2018-09-18','robbery','Port Saint Lucie','United States','');INSERT INTO crime_scene VALUES('2018-01-08','theft','West Hartford','United States','“What blighter was that?” inquired Tommy. “Perfectly sickening the way those brass hats drove from the War Office to the Savoy, and from the Savoy to the War Office!”');INSERT INTO crime_scene VALUES('2018-09-26','murder','Phoenix','United States','');INSERT INTO crime_scene VALUES('2018-09-05','theft','Cincinnati','United States','');INSERT INTO crime_scene VALUES('2018-03-02','arson','El Paso','United States','Tuppence smiled a little. She felt that Whittington had scored.');INSERT INTO crime_scene VALUES('2018-09-18','robbery','Reading','United States','');INSERT INTO crime_scene VALUES('2018-07-30','assault','Topeka','United States','“Very little indeed,” answered Tuppence, and was pleased to note that Whittington’s uneasiness was augmented instead of allayed. To have boasted that she knew a lot might have raised doubts in his mind.');INSERT INTO crime_scene VALUES('2018-02-21','fraud','Pinellas Park','United States','''‘What size do you want to be?’ it asked.');INSERT INTO crime_scene VALUES('2018-03-03','theft','Englewood','United States','''');INSERT INTO crime_scene VALUES('2018-02-18','arson','Tucson','United States','''‘But about his toes?’ the Mock Turtle persisted. ‘How COULD he turn them');INSERT INTO crime_scene VALUES('2018-09-17','theft','Denver','United States','');INSERT INTO crime_scene VALUES('2018-02-28','murder','Birmingham','United States','');INSERT INTO crime_scene VALUES('2018-09-12','assault','Miami','United States','');INSERT INTO crime_scene VALUES('2018-07-29','fraud','San Diego','United States','');INSERT INTO crime_scene VALUES('2018-08-08','murder','Houston','United States','“My dear Mr. Whittington,” she said, “let us by all means lay our cards upon the table. And pray do not be so angry. You heard me say yesterday that I proposed to live by my wits. It seems to me that I have now proved I have some wits to live by! I admit I have knowledge of a certain name, but perhaps my knowledge ends there.”');INSERT INTO crime_scene VALUES('2018-01-07','fraud','Little Rock','United States','No, old thing, not in riotous dissipation. No such luck! The cost of living—ordinary plain, or garden living nowadays is, I assure you, if you do not know');INSERT INTO crime_scene VALUES('2018-09-02','murder','Atlanta','United States','The girl counted the notes in a businesslike manner, secured them in her handbag, and rose.');INSERT INTO crime_scene VALUES('2018-01-08','murder','Tampa','United States','The tea came at last, and Tuppence, rousing herself from a fit of meditation, poured it out.');INSERT INTO crime_scene VALUES('2018-02-24','robbery','Pompano Beach','United States','Tuppence sat down on the chair facing him. She looked particularly small and demure this morning. She sat there meekly with downcast eyes whilst Mr. Whittington sorted and rustled amongst his papers. Finally he pushed them away, and leaned over the desk.');INSERT INTO crime_scene VALUES('2018-09-13','assault','Vancouver','United States','''');INSERT INTO crime_scene VALUES('2018-11-02','robbery','Houston','United States','''It was so long since she had been anything near the right size');INSERT INTO crime_scene VALUES('2018-09-27','fraud','Cleveland','United States','“All in good time. What an awful place Piccadilly Circus is. There’s a huge bus bearing down on us. It would be too terrible if they killed the five-pound notes!”');INSERT INTO crime_scene VALUES('2018-01-09','assault','Fort Worth','United States','“There’s not so much promotion in mine,” said Tommy regretfully, “and a great deal less variety. I went out to France again, as you know. Then they sent me to Mesopotamia, and I got wounded for the second time, and went into hospital out there. Then I got stuck in Egypt till the Armistice happened, kicked my heels there some time longer, and, as I told you, finally got demobbed. And, for ten long, weary months I’ve been job hunting! There aren’t any jobs! And, if there were, they wouldn’t give ‘em to me. What good am I? What do I know about business? Nothing.”

');INSERT INTO crime_scene VALUES('2018-03-03','theft','Los Angeles','United States','“Been playing with me, have you, all the time, like a cat and mouse? Knew all the time what I wanted you for, but kept up the comedy. Is that it, eh?” He was cooling down. The red colour was ebbing out of his face. He eyed her keenly. “Who’s been blabbing? Rita?”');INSERT INTO crime_scene VALUES('2018-03-08','fraud','Honolulu','United States','''');INSERT INTO crime_scene VALUES('2018-07-30','assault','Salt Lake City','United States','');INSERT INTO crime_scene VALUES('2018-02-25','theft','Nashville','United States','');INSERT INTO crime_scene VALUES('2018-09-12','arson','Los Angeles','United States','');INSERT INTO crime_scene VALUES('2018-07-28','arson','Savannah','United States','');INSERT INTO crime_scene VALUES('2018-01-09','assault','Champaign','United States','“I’ve forgotten his name now,” confessed Tuppence. “To resume, that was in a way the apex of my career. I next entered a Government office. We had several very enjoyable tea parties. I had intended to become a land girl, a postwoman, and a bus conductress by way of rounding off my career—but the Armistice intervened! I clung to the office with the true limpet touch for many long months, but, alas, I was combed out at last. Since then I’ve been looking for a job. Now then—your turn.”');INSERT INTO crime_scene VALUES('2018-03-09','theft','Orlando','United States','');INSERT INTO crime_scene VALUES('2018-03-10','arson','Sioux City','United States','');INSERT INTO crime_scene VALUES('2018-03-02','assault','Buffalo','United States','');INSERT INTO crime_scene VALUES('2018-09-11','theft','Erie','United States','');INSERT INTO crime_scene VALUES('2018-08-03','assault','San Diego','United States','');INSERT INTO crime_scene VALUES('2018-09-20','arson','Daytona Beach','United States','');INSERT INTO crime_scene VALUES('2018-03-07','robbery','Pittsburgh','United States','''');INSERT INTO crime_scene VALUES('2018-02-23','fraud','Jackson','United States','Later, in her tiny cubicle at the top of the house she munched buns and reflected on the future. What was the Esthonia Glassware Co., and what earthly need could it have for her services? A pleasurable thrill of excitement made Tuppence tingle. At any rate, the country vicarage had retreated into the background again. The morrow held possibilities.');INSERT INTO crime_scene VALUES('2018-03-04','fraud','Huntington','United States','');INSERT INTO crime_scene VALUES('2018-07-30','fraud','Raleigh','United States','');INSERT INTO crime_scene VALUES('2018-09-17','murder','Naples','United States','“No,” said Tuppence thoughtfully, “he didn’t believe it. That’s the curious part about speaking the truth. No one does believe it. I found that out this morning. Now let’s go to lunch. How about the Savoy?”');INSERT INTO crime_scene VALUES('2018-12-27','theft','Atlanta','United States','');INSERT INTO crime_scene VALUES('2018-01-08','theft','Tampa','United States','Ninth month: Promoted to sweeping out wards, where I found a friend of my childhood in Lieutenant Thomas Beresford (bow, Tommy!), whom I had not seen for five long years. The meeting was affecting! Tenth month: Reproved by matron for visiting the pictures in company with one of the patients, namely: the aforementioned Lieutenant Thomas Beresford. Eleventh and twelfth months: Parlourmaid duties resumed with entire success. At the end of the year left hospital in a blaze of glory. After that, the talented Miss Cowley drove successively a trade delivery van, a motor-lorry and a general! The last was the pleasantest. He was quite a young general!”');INSERT INTO crime_scene VALUES('2018-09-16','theft','Cleveland','United States','');INSERT INTO crime_scene VALUES('2018-03-06','robbery','Jamaica','United States','''');INSERT INTO crime_scene VALUES('2018-01-08','murder','Greeley','United States','They were an essentially modern-looking couple as they sat there. Tuppence had no claim to beauty, but there was character and charm in the elfin lines of her little face, with its determined chin and large, wide-apart grey eyes that looked mistily out from under straight, black brows. She wore a small bright green toque over her black bobbed hair, and her extremely short and rather shabby skirt revealed a pair of uncommonly dainty ankles. Her appearance presented a valiant attempt at smartness.');INSERT INTO crime_scene VALUES('2018-09-06','arson','Stockton','United States','“Let’s give Tommy a surprise!” murmured Tuppence, and hailed a taxi.');INSERT INTO crime_scene VALUES('2018-09-02','assault','Jacksonville','United States','''');INSERT INTO crime_scene VALUES('2018-03-03','assault','El Paso','United States','');INSERT INTO crime_scene VALUES('2018-08-09','arson','Louisville','United States','');INSERT INTO crime_scene VALUES('2018-03-13','murder','El Paso','United States','''‘What did they draw?’ said Alice');INSERT INTO crime_scene VALUES('2018-01-06','theft','Louisville','United States','The girl assenting, they started walking down Dover Street towards Piccadilly.');INSERT INTO crime_scene VALUES('2018-02-24','theft','Durham','United States','ave a fit! But somehow I don’t see Mr. Whittington in the role of the gay deceiver.”

“Yes,” continued Whittington. “What could be more delightful? To put the clock back a few years—a very few, I am sure—and re-enter one of those charming pensionnats de jeunes filles with which Paris abounds——”

');INSERT INTO crime_scene VALUES('2018-09-09','robbery','Richmond','United States','''');INSERT INTO crime_scene VALUES('2018-02-27','theft','Oklahoma City','United States','''');INSERT INTO crime_scene VALUES('2018-02-27','murder','Boston','United States','');INSERT INTO crime_scene VALUES('2018-08-12','arson','Garden Grove','United States','“You’re about the limit, that’s what you are,” growled Whittington, with a sort of unwilling admiration. “You took me in all right. Thought you were quite a meek little kid with just enough brains for my purpose.”');INSERT INTO crime_scene VALUES('2018-11-04','fraud','Springfield','United States','');INSERT INTO crime_scene VALUES('2018-09-19','arson','Minneapolis','United States','');INSERT INTO crime_scene VALUES('2018-07-31','fraud','Austin','United States','');INSERT INTO crime_scene VALUES('2018-03-14','assault','Atlanta','United States','''‘Call it what you like');INSERT INTO crime_scene VALUES('2018-09-11','murder','Indianapolis','United States','The moment was not quite so triumphant as it ought to have been. To begin with, the resources of Tommy’s pockets were somewhat limited. In the end the fare was managed, the lady recollecting a plebeian twopence, and the driver, still holding the varied assortment of coins in his hand, was prevailed upon to move on, which he did after one last hoarse demand as to what the gentleman thought he was giving him?');INSERT INTO crime_scene VALUES('2018-02-22','fraud','Montgomery','United States','And with a short, sharp nod of her head she walked briskly onward. As a result of further meditations, however, she turned aside from the direct route and entered a post office. There she pondered for some moments, a telegraph form in her hand. The thought of a possible five shillings spent unnecessarily spurred her to action, and she decided to risk the waste of ninepence.');INSERT INTO crime_scene VALUES('2018-03-04','robbery','Atlanta','United States','');INSERT INTO crime_scene VALUES('2018-09-24','robbery','Honolulu','United States','“How about the Ritz?”

“On second thoughts, I prefer the Piccadilly. It’s nearer. We shan’t have to take another taxi. Come along.”');INSERT INTO crime_scene VALUES('2018-02-26','assault','Santa Rosa','United States','Yet you speak with a slight American accent?');INSERT INTO crime_scene VALUES('2018-08-09','theft','Seattle','United States','');INSERT INTO crime_scene VALUES('2018-02-23','murder','Brooklyn','United States','It was a long time before Tuppence went to sleep that night, and, when at length she did, she dreamed that Mr. Whittington had set her to washing up a pile of Esthonia Glassware, which bore an unaccountable resemblance to hospital plates!');INSERT INTO crime_scene VALUES('2018-09-13','robbery','Fort Worth','United States','''');INSERT INTO crime_scene VALUES('2018-09-14','assault','Farmington','United States','');INSERT INTO crime_scene VALUES('2018-08-08','murder','Durham','United States','');INSERT INTO crime_scene VALUES('2018-03-13','theft','Miami','United States','');INSERT INTO crime_scene VALUES('2018-01-04','theft','Brooklyn','United States','“It must be!” he muttered to himself. “Yes—it is the only way.” Then aloud he said abruptly: “You are an American?”');INSERT INTO crime_scene VALUES('2018-08-11','robbery','Seminole','United States','');INSERT INTO crime_scene VALUES('2018-08-07','robbery','San Jose','United States','');INSERT INTO crime_scene VALUES('2018-09-14','fraud','Portland','United States','“I was afraid I might be late and keep you waiting,” said Tuppence gently.');INSERT INTO crime_scene VALUES('2018-03-15','arson','Houston','United States','''‘I quite agree with you');INSERT INTO crime_scene VALUES('2018-01-07','arson','Stockton','United States','You always were a shocking liar,” said Tuppence severely, “though you did once persuade Sister Greenbank that the doctor had ordered you beer as a tonic, but forgotten to write it on the chart. Do you remember?');INSERT INTO crime_scene VALUES('2018-03-09','assault','Garland','United States','Tuppence shook her head. She was doubtful as to how long she could sustain this illusion, but she realized the importance of not dragging an unknown Rita into it.');INSERT INTO crime_scene VALUES('2018-09-01','theft','Grand Forks','United States','');INSERT INTO crime_scene VALUES('2018-08-10','robbery','Springfield','United States','');INSERT INTO crime_scene VALUES('2018-01-03','robbery','Garland','United States','A man’s voice beside her made her start and turn. She had noticed the speaker more than once amongst the first-class passengers. There had been a hint of mystery about him which had appealed to her imagination. He spoke to no one. If anyone spoke to him he was quick to rebuff the overture. Also he had a nervous way of looking over his shoulder with a swift, suspicious glance.');INSERT INTO crime_scene VALUES('2018-09-04','theft','Birmingham','United States','');INSERT INTO crime_scene VALUES('2018-08-31','robbery','Grand Forks','United States','');INSERT INTO crime_scene VALUES('2018-08-05','robbery','San Diego','United States','The last five words took Tuppence’s fancy mightily, especially after a meagre breakfast and a supper of buns the night before. Her present part was of the adventuress rather than the adventurous order, but she did not deny its possibilities. She sat up and smiled with the air of one who has the situation thoroughly well in hand.');INSERT INTO crime_scene VALUES('2018-09-16','murder','Des Moines','United States','''');INSERT INTO crime_scene VALUES('2018-02-21','fraud','Tucson','United States','Tuppence took it and scrutinized it carefully. It bore the inscription, “Mr. Edward Whittington.” Below the name were the words “Esthonia Glassware Co.,” and the address of a city office. Mr. Whittington spoke again:');INSERT INTO crime_scene VALUES('2018-02-23','arson','Kansas City','United States','Disdaining the spiky pen and thick, black treacle which a beneficent Government had provided, Tuppence drew out Tommy’s pencil which she had retained and wrote rapidly: “Don’t put in advertisement. Will explain to-morrow.” She addressed it to Tommy at his club, from which in one short month he would have to resign, unless a kindly fortune permitted him to renew his subscription.');INSERT INTO crime_scene VALUES('2018-08-10','arson','Baton Rouge','United States','');INSERT INTO crime_scene VALUES('2018-01-10','murder','Saint Louis','United States','“Yes, it would have been a bit rough on the mater. As you know, I was all she had. Old boy hated her—wanted to get me away from her. Just a bit of spite.”');INSERT INTO crime_scene VALUES('2018-02-28','fraud','Fresno','United States','''');INSERT INTO crime_scene VALUES('2018-03-02','fraud','Pensacola','United States','');INSERT INTO crime_scene VALUES('2018-09-13','arson','Pinellas Park','United States','');INSERT INTO crime_scene VALUES('2018-09-05','arson','Arlington','United States','');

